def choose_move(observation):
    sx, sy = observation.get("self_position", (0,0))
    ox, oy = observation.get("opponent_position", (0,0))
    env = observation.get("environment_name", "resource_collection")

    # Defensive access
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)

    # Helper function to get direction towards target
    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    # Pursuit/Evasion part
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            # Chase opponent
            return move_towards(ox, oy)
        else:
            # Evade opponent: move away
            dx = 0
            dy = 0
            if ox > sx:
                dx = -1
            elif ox < sx:
                dx = 1
            if oy > sy:
                dy = -1
            elif oy < sy:
                dy = 1
            return [dx, dy]

    # Territory Control
    if env == "territory_control":
        unclaimed = observation.get("unclaimed_cells") or []
        opponent_territory = observation.get("opponent_territory") or []
        targets = unclaimed if unclaimed else opponent_territory
        if not targets:
            return [0, 0]
        best_target = min(targets, key=lambda pos: abs(pos[0]-sx)+abs(pos[1]-sy))
        return move_towards(best_target[0], best_target[1])

    # Resource collection (or default)
    resources = observation.get("resources") or []
    if resources:
        best_resource = min(resources, key=lambda pos: abs(pos[0]-sx)+abs(pos[1]-sy))
        return move_towards(best_resource[0], best_resource[1])
    else:
        # No resources, move randomly towards opponent or center
        # To keep it simple, move towards opponent if known, else center
        target_x, target_y = ox, oy
        if "environment_name" not in observation:
            target_x, target_y = grid_width//2, grid_height//2
        return move_towards(target_x, target_y)

